art_scale=art_width/ART_WIDTH
arrow_profiles=[]
for contour in reference_segments:
    edges=[]
    for seg in contour:
        pts=[((x-ART_CENTER_X)*art_scale,-(y-ART_CENTER_Y)*art_scale)
             for x,y in seg["points"]]
        edges.append(Line(*pts) if seg["kind"]=="line" else Bezier(*pts))
    arrow_profiles.append(make_face(Wire(edges)))
assert len(arrow_profiles)==6
assert all(len(p.faces())==1 and p.is_valid for p in arrow_profiles)
arrow_profile=arrow_profiles[0]
for p in arrow_profiles[1:]:
    arrow_profile+=p
assert len(arrow_profile.faces())==6, "The six original reference ribbons must stay separate"

# Preserve the accepted symmetric white backing proportions, independent of
# the new artwork aspect ratio. These are its established support datums
# at nominal 18 mm artwork width, before the adjustable outline margin.
OUTLINE_REF_WIDTH=18.0
OUTLINE_REF_SIDE=9.244692110790289
OUTLINE_REF_END=8.877828055183144
side_support=OUTLINE_REF_SIDE*(art_width/OUTLINE_REF_WIDTH)+border
end_support=OUTLINE_REF_END*(art_width/OUTLINE_REF_WIDTH)+border
from math import sin,cos,radians
normals=[(cos(radians(30+60*i)),sin(radians(30+60*i))) for i in range(6)]
supports=[side_support,end_support,side_support,side_support,end_support,side_support]
envelope_vertices=[]
for i in range(6):
    ax,ay=normals[i]
    bx,by=normals[(i+1)%6]
    da,db=supports[i],supports[(i+1)%6]
    determinant=ax*by-ay*bx
    envelope_vertices.append(((da*by-ay*db)/determinant,(ax*db-da*bx)/determinant))
envelope=Polygon(*envelope_vertices,align=None)
base_profile=fillet(envelope.vertices(),radius=corner_radius)
assert (arrow_profile-base_profile).area<1e-7
base=extrude(base_profile,amount=base_thickness,dir=(0,0,1))
arrows=Pos(0,0,base_thickness)*extrude(arrow_profile,amount=arrow_rise,dir=(0,0,1))
badge_solid=base+arrows
assert badge_solid.is_valid and len(badge_solid.solids())==1
assert abs(badge_solid.bounding_box().size.Z-base_thickness-arrow_rise)<1e-5
badge_solid.color=srgb("#ffffff")
print("Reference ribbons",len(arrow_profiles),"edges",len(arrow_profile.edges()))
print("Base/arrow/total height",base_thickness,arrow_rise,base_thickness+arrow_rise)
print("Arrow footprint",arrow_profile.bounding_box().size)
publish("recycle_badge",badge_solid,"07 一体回收标志",material="petg")
